else
  echo " ERROR: base64 is not available."; exit 1
fi

git apply --check .v1016.patch || {
  echo
  echo " ERROR: the patch does not match your current main branch."
  echo " (It expects v1.0.15.) Make sure you pulled first, then run me again."
  exit 1
}
git apply .v1016.patch || {
  echo
  echo " ERROR: applying the patch failed."
  echo " To undo the partial change run:  git checkout -- ."
  exit 1
}

# --- Bump the version to 1.0.16 ---
sed -i.bak 's/"version": "1.0.15"/"version": "1.0.16"/' package.json && rm -f package.json.bak

echo " Committing and pushing..."
git add package.json src/App.tsx src/admin/adminApi.ts src/admin/views/AiMonitor.tsx src/components/SkySplash.tsx src/services/aiChat.ts test/aiChatError.test.mjs test/workerAi.test.mjs test/workerConfig.test.mjs worker/src/ai.ts worker/src/index.ts
git commit -m "v1.0.16: AI failures tell the truth (stream CORS + smart offline-vs-service diagnosis + student-side errors reach the admin log), AI Monitor error log no longer stuck, admin-enlarged icons grow in place without shifting, publish failures explain themselves and diagnostics dry-run the publish path" || {
  git reset -q 2>/dev/null
  git checkout -q -- . 2>/dev/null
  git clean -qf test/aiChatError.test.mjs 2>/dev/null
  rm -f .v1016.b64 .v1016.patch
  echo
  echo " ERROR: the commit failed. I undid the v1.0.16 changes so you can try again."
  exit 1
}
git push origin main || {
  echo
  echo " PUSH FAILED - but the code IS committed locally on main."
  echo " Fix the connection, then run:  git push origin main"
  exit 1
}

rm -f .v1016.b64 .v1016.patch
echo
echo ============================================
echo " DONE - v1.0.16 is committed and pushed to main."
echo
echo " What changed (the 4 live bugs are fixed):"
echo "  - AI: students are never wrongly told 'no internet' - the app now"
echo "    proves whether it is really offline or the AI service itself"
echo "    failed, and tells them the true reason. Student-side failures"
echo "    now also appear in the admin AI Monitor error log."
echo "  - AI Monitor: the error log no longer sits on 'Loading error log...'"
echo "    forever - a real failure shows the problem + a Retry button, and the"
echo "    endpoint can no longer 500 silently."
echo "  - Icons: admin-enlarged icons now INCREASE IN SIZE IN PLACE in the"
echo "    student view (header, tiles, Sky Dash, landing) - no shifting,"
echo "    no clipping, no repositioning."
echo "  - Publish: a failing publish now explains itself (catalog too big"
echo "    for the database = use smaller icon/logo images; real database"
echo "    errors are shown). Diagnostics now dry-run the publish path, so"
echo "    'all healthy' can never coexist with a broken publish."
echo
echo " The student site + admin update on the next normal load."
echo ============================================